SELECT e.event_id, m.case_id, e.activity, e.timestamp FROM (SELECT * FROM (SELECT 'EX:' || result_id event_id, student_id case_id, 'Degree Examination Taken' activity, examination_date timestamp FROM degree_examination_result UNION ALL SELECT 'REG:' || student_id || ':' || course_id event_id, student_id case_id, 'Course Registered' activity, registration_time timestamp FROM registration UNION ALL SELECT 'GRADE:' || g.assignment_id || ':' || g.instructor_id || ':' || g.grading_time event_id, a.student_id case_id, 'Assignment Graded' activity, g.grading_time timestamp FROM assignment_grading g JOIN assignment a ON a.assignment_id=g.assignment_id WHERE g.grading_kind='ORIGINAL' UNION ALL SELECT 'SIM:' || student_id || ':' || module_id || ':' || simulation_date event_id, student_id case_id, 'Simulation Experiment Completed' activity, simulation_date timestamp FROM student_simulation_experiment_result UNION ALL SELECT 'THESIS:' || thesis_id event_id, student_id case_id, 'Thesis Submitted' activity, submission_date timestamp FROM thesis) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':3' event_id,'Assignment Revision Requested' activity,assignment_revision_requested_at timestamp,assignment_id object_key FROM assignment WHERE assignment_revision_requested_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':4' event_id,'Assignment Resubmitted' activity,assignment_resubmitted_at timestamp,assignment_id object_key FROM assignment WHERE assignment_resubmitted_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:thesis:' || thesis_id || ':3' event_id,'Thesis Revision Requested' activity,thesis_revision_requested_at timestamp,thesis_id object_key FROM thesis WHERE thesis_revision_requested_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:thesis:' || thesis_id || ':4' event_id,'Thesis Resubmitted' activity,thesis_resubmitted_at timestamp,thesis_id object_key FROM thesis WHERE thesis_resubmitted_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:simulation_module:' || module_id || ':1' event_id,'Simulation Module Published' activity,simulation_module_published_at timestamp,module_id object_key FROM simulation_module WHERE simulation_module_published_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:simulation_module:' || module_id || ':2' event_id,'Simulation Module Validated' activity,simulation_module_validated_at timestamp,module_id object_key FROM simulation_module WHERE simulation_module_validated_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:simulation_module:' || module_id || ':3' event_id,'Simulation Module Released' activity,simulation_module_released_at timestamp,module_id object_key FROM simulation_module WHERE simulation_module_released_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:simulation_module:' || module_id || ':4' event_id,'Simulation Module Retired' activity,simulation_module_retired_at timestamp,module_id object_key FROM simulation_module WHERE simulation_module_retired_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:student_simulation_experiment_result:' || student_id || ':' || module_id || ':' || simulation_date || ':1' event_id,'Simulation Run Scheduled' activity,simulation_run_scheduled_at timestamp,student_id || ':' || module_id || ':' || simulation_date object_key FROM student_simulation_experiment_result WHERE simulation_run_scheduled_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:student_simulation_experiment_result:' || student_id || ':' || module_id || ':' || simulation_date || ':2' event_id,'Simulation Run Started' activity,simulation_run_started_at timestamp,student_id || ':' || module_id || ':' || simulation_date object_key FROM student_simulation_experiment_result WHERE simulation_run_started_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:student_simulation_experiment_result:' || student_id || ':' || module_id || ':' || simulation_date || ':3' event_id,'Simulation Output Reviewed' activity,simulation_output_reviewed_at timestamp,student_id || ':' || module_id || ':' || simulation_date object_key FROM student_simulation_experiment_result WHERE simulation_output_reviewed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:student_simulation_experiment_result:' || student_id || ':' || module_id || ':' || simulation_date || ':4' event_id,'Simulation Result Accepted' activity,simulation_result_accepted_at timestamp,student_id || ':' || module_id || ':' || simulation_date object_key FROM student_simulation_experiment_result WHERE simulation_result_accepted_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:course:' || course_id || ':1' event_id,'Course Offering Proposed' activity,course_offering_proposed_at timestamp,course_id object_key FROM course WHERE course_offering_proposed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:course:' || course_id || ':2' event_id,'Course Offering Approved' activity,course_offering_approved_at timestamp,course_id object_key FROM course WHERE course_offering_approved_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:course:' || course_id || ':3' event_id,'Course Offering Published' activity,course_offering_published_at timestamp,course_id object_key FROM course WHERE course_offering_published_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:course:' || course_id || ':4' event_id,'Course Offering Closed' activity,course_offering_closed_at timestamp,course_id object_key FROM course WHERE course_offering_closed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:task:' || task_id || ':1' event_id,'Design Task Created' activity,design_task_created_at timestamp,task_id object_key FROM task WHERE design_task_created_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:task:' || task_id || ':2' event_id,'Design Task Approved' activity,design_task_approved_at timestamp,task_id object_key FROM task WHERE design_task_approved_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:task:' || task_id || ':3' event_id,'Design Task Published' activity,design_task_published_at timestamp,task_id object_key FROM task WHERE design_task_published_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:task:' || task_id || ':4' event_id,'Design Task Closed' activity,design_task_closed_at timestamp,task_id object_key FROM task WHERE design_task_closed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':1' event_id, 'Registration Requested' activity, registration_requested_at timestamp,student_id || ':' || course_id object_key FROM registration WHERE registration_requested_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':2' event_id, 'Registration Approved' activity, registration_approved_at timestamp,student_id || ':' || course_id object_key FROM registration WHERE registration_approved_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':3' event_id, 'Course Started' activity, course_started_at timestamp,student_id || ':' || course_id object_key FROM registration WHERE course_started_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':4' event_id, 'Course Assessment Completed' activity, course_assessment_completed_at timestamp,student_id || ':' || course_id object_key FROM registration WHERE course_assessment_completed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:registration:' || student_id || ':' || course_id || ':5' event_id, 'Course Grade Finalized' activity, course_grade_finalized_at timestamp,student_id || ':' || course_id object_key FROM registration WHERE course_grade_finalized_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:degree_examination_result:' || result_id || ':1' event_id, 'Examination Scheduled' activity, examination_scheduled_at timestamp,result_id object_key FROM degree_examination_result WHERE examination_scheduled_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:degree_examination_result:' || result_id || ':2' event_id, 'Examination Checked In' activity, examination_checked_in_at timestamp,result_id object_key FROM degree_examination_result WHERE examination_checked_in_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:degree_examination_result:' || result_id || ':3' event_id, 'Examination Score Published' activity, examination_score_published_at timestamp,result_id object_key FROM degree_examination_result WHERE examination_score_published_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:degree_examination_result:' || result_id || ':4' event_id, 'Examination Result Reviewed' activity, examination_result_reviewed_at timestamp,result_id object_key FROM degree_examination_result WHERE examination_result_reviewed_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':1' event_id, 'Assignment Assigned' activity, assignment_assigned_at timestamp,assignment_id object_key FROM assignment WHERE assignment_assigned_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':2' event_id, 'Assignment Submitted' activity, assignment_submitted_at timestamp,assignment_id object_key FROM assignment WHERE assignment_submitted_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':' || CASE WHEN assignment_revision_requested_at IS NOT NULL THEN '6' ELSE '3' END event_id,'Assignment Grade Finalized' activity,assignment_grade_finalized_at timestamp,assignment_id object_key FROM assignment WHERE assignment_grade_finalized_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:thesis:' || thesis_id || ':1' event_id, 'Thesis Draft Registered' activity, thesis_draft_registered_at timestamp,thesis_id object_key FROM thesis WHERE thesis_draft_registered_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:thesis:' || thesis_id || ':2' event_id, 'Thesis Review Started' activity, thesis_review_started_at timestamp,thesis_id object_key FROM thesis WHERE thesis_review_started_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT 'LC:thesis:' || thesis_id || ':' || CASE WHEN thesis_revision_requested_at IS NOT NULL THEN '5' ELSE '3' END event_id,'Thesis Accepted' activity,thesis_accepted_at timestamp,thesis_id object_key FROM thesis WHERE thesis_accepted_at IS NOT NULL) UNION ALL SELECT event_id, NULL case_id,activity,timestamp FROM (SELECT reassessment_event_id event_id,'Assignment Regraded' activity,grading_time timestamp,assignment_id || ':' || instructor_id || ':' || grading_time object_key FROM assignment_grading WHERE grading_kind='REASSESSMENT')) e JOIN (SELECT 'THESIS:' || thesis_id event_id, thesis_id case_id FROM thesis UNION ALL SELECT e.event_id,o.thesis_id case_id FROM (SELECT 'LC:thesis:' || thesis_id || ':3' event_id,'Thesis Revision Requested' activity,thesis_revision_requested_at timestamp,thesis_id object_key FROM thesis WHERE thesis_revision_requested_at IS NOT NULL) e JOIN thesis o ON o.thesis_id=e.object_key UNION ALL SELECT e.event_id,o.thesis_id case_id FROM (SELECT 'LC:thesis:' || thesis_id || ':4' event_id,'Thesis Resubmitted' activity,thesis_resubmitted_at timestamp,thesis_id object_key FROM thesis WHERE thesis_resubmitted_at IS NOT NULL) e JOIN thesis o ON o.thesis_id=e.object_key UNION ALL SELECT e.event_id,o.thesis_id case_id FROM (SELECT 'LC:thesis:' || thesis_id || ':1' event_id, 'Thesis Draft Registered' activity, thesis_draft_registered_at timestamp,thesis_id object_key FROM thesis WHERE thesis_draft_registered_at IS NOT NULL) e JOIN thesis o ON o.thesis_id=e.object_key UNION ALL SELECT e.event_id,o.thesis_id case_id FROM (SELECT 'LC:thesis:' || thesis_id || ':2' event_id, 'Thesis Review Started' activity, thesis_review_started_at timestamp,thesis_id object_key FROM thesis WHERE thesis_review_started_at IS NOT NULL) e JOIN thesis o ON o.thesis_id=e.object_key UNION ALL SELECT e.event_id,o.thesis_id case_id FROM (SELECT 'LC:thesis:' || thesis_id || ':' || CASE WHEN thesis_revision_requested_at IS NOT NULL THEN '5' ELSE '3' END event_id,'Thesis Accepted' activity,thesis_accepted_at timestamp,thesis_id object_key FROM thesis WHERE thesis_accepted_at IS NOT NULL) e JOIN thesis o ON o.thesis_id=e.object_key) m ON m.event_id=e.event_id ORDER BY m.case_id,e.timestamp,e.event_id;
